import React, { useState } from 'react';
import Login from './pages/SignIn.js';

function App() {
  // Use this state to show/hide the login modal
  const [isLoginOpen, setIsLoginOpen] = useState(true);

  const handleLoginSuccess = () => {
    alert("Access Granted. Initializing Dashboard...");
    setIsLoginOpen(false);
  };

  return (
    <div className="App">
      {/* If isLoginOpen is true, show the Login component */}
      <Login 
        isOpen={isLoginOpen} 
        onClose={() => setIsLoginOpen(false)} 
        onLogin={handleLoginSuccess} 
      />

      {!isLoginOpen && (
        <div className="flex items-center justify-center h-screen bg-[#47510B] text-[#CAD23C] font-black italic text-4xl">
          COMMAND CENTER ONLINE
        </div>
      )}
    </div>
  );
}

export default App;
